// Package db owns the Postgres connection pool, the unit of work (WithTx with retry on serialization failures and
// deadlocks), advisory locks and the goose migrations. Typed queries are generated by sqlc into internal/db/dbq.
package db

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Open connects to Postgres (UTC session time zone) and pings it.
func Open(ctx context.Context, url string) (*pgxpool.Pool, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("parse DATABASE_URL: %w", err)
	}
	cfg.ConnConfig.RuntimeParams["timezone"] = "UTC"
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, err
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping database: %w", err)
	}
	return pool, nil
}

// OpenWithRetry waits for Postgres on a cold start (container boot order).
func OpenWithRetry(ctx context.Context, url string, attempts int, wait time.Duration, onWait func(int)) (*pgxpool.Pool, error) {
	var lastErr error
	for i := 1; i <= attempts; i++ {
		pool, err := Open(ctx, url)
		if err == nil {
			return pool, nil
		}
		lastErr = err
		if onWait != nil {
			onWait(i)
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(wait):
		}
	}
	return nil, lastErr
}

// MaxAttempts is how often WithTx runs a transaction that failed with a serialization failure or deadlock.
const MaxAttempts = 3

// Retryable reports whether err is a transient conflict that a fresh transaction can resolve.
func Retryable(err error) bool {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return pgErr.Code == "40001" || pgErr.Code == "40P01" // serialization_failure, deadlock_detected
	}
	return false
}

// TxOptions defaults to READ COMMITTED; actions take row locks (SELECT … FOR UPDATE) on what they change.
type TxOptions = pgx.TxOptions

// WithTx runs fn in one transaction and commits when it returns nil. Serialization failures and deadlocks are
// retried (fn must therefore be safe to run again: it only touches the database through tx).
func WithTx(ctx context.Context, pool *pgxpool.Pool, opts pgx.TxOptions, fn func(pgx.Tx) error) error {
	var err error
	for attempt := 1; attempt <= MaxAttempts; attempt++ {
		err = pgx.BeginTxFunc(ctx, pool, opts, fn)
		if err == nil || !Retryable(err) || ctx.Err() != nil {
			return err
		}
		time.Sleep(time.Duration(attempt*attempt) * 5 * time.Millisecond)
	}
	return err
}

// Advisory lock keys (pg_advisory_*). Other modules pick their own keys outside this block.
const (
	LockMigrate   int64 = 0x5e3a_0001
	LockJobs      int64 = 0x5e3a_0002
	LockRetention int64 = 0x5e3a_0003
)

// WithSessionLock runs fn while holding a session-level advisory lock on one pooled connection, so work spread over
// several transactions (e.g. the retention job) runs on one instance at a time. It returns false without calling fn
// when another session holds the lock.
func WithSessionLock(ctx context.Context, pool *pgxpool.Pool, key int64, fn func(ctx context.Context) error) (bool, error) {
	conn, err := pool.Acquire(ctx)
	if err != nil {
		return false, err
	}
	defer conn.Release()
	var ok bool
	if err := conn.QueryRow(ctx, `SELECT pg_try_advisory_lock($1)`, key).Scan(&ok); err != nil || !ok {
		return false, err
	}
	defer func() {
		// A fresh context: the unlock must happen even when ctx was cancelled during fn.
		uctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if _, err := conn.Exec(uctx, `SELECT pg_advisory_unlock($1)`, key); err != nil {
			_ = conn.Conn().Close(uctx) // dropping the connection releases the lock
		}
	}()
	return true, fn(ctx)
}

// TryXactLock takes a transaction-scoped advisory lock without waiting. It is released at commit/rollback.
func TryXactLock(ctx context.Context, tx pgx.Tx, key int64) (bool, error) {
	var ok bool
	err := tx.QueryRow(ctx, `SELECT pg_try_advisory_xact_lock($1)`, key).Scan(&ok)
	return ok, err
}

// IsNotFound reports a query that returned no row.
func IsNotFound(err error) bool { return errors.Is(err, pgx.ErrNoRows) }

// IsUniqueViolation reports a unique constraint violation (optionally a specific constraint).
func IsUniqueViolation(err error, constraint string) bool {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == "23505" {
		return constraint == "" || pgErr.ConstraintName == constraint
	}
	return false
}
